import React, { useState } from "react";
import { Box, AppBar, Toolbar, Typography, Drawer, List, ListItem, ListItemIcon, ListItemText } from "@mui/material";
import { Dashboard as DashboardIcon, HowToVote, BarChart, ExitToApp } from "@mui/icons-material";

const drawerWidth = 240;

const Dashboard = () => {
  const [activeTab, setActiveTab] = useState("Dashboard");

  return (
    <Box sx={{ display: "flex", minHeight: "100vh" }}>
      {/* Top Bar */}
      <AppBar position="fixed" sx={{ width: "100%", backgroundColor: "#007bff", zIndex: (theme) => theme.zIndex.drawer + 1 }}>
        <Toolbar>
          <Typography variant="h6" noWrap component="div">
            SRC E-Voting System
          </Typography>
        </Toolbar>
      </AppBar>
      
      {/* Sidebar Navigation */}
      <Drawer
        variant="permanent"
        sx={{
          width: drawerWidth,
          flexShrink: 0,
          [`& .MuiDrawer-paper`]: { width: drawerWidth, boxSizing: "border-box", backgroundColor: "white", mt: 8 },
        }}
      >
        <Toolbar />
        <List>
          <ListItem button onClick={() => setActiveTab("Dashboard")}> 
            <ListItemIcon><DashboardIcon /></ListItemIcon>
            <ListItemText primary="Dashboard" />
          </ListItem>
          <ListItem button onClick={() => setActiveTab("Vote")}> 
            <ListItemIcon><HowToVote /></ListItemIcon>
            <ListItemText primary="Vote" />
          </ListItem>
          <ListItem button onClick={() => setActiveTab("Results")}> 
            <ListItemIcon><BarChart /></ListItemIcon>
            <ListItemText primary="Results" />
          </ListItem>
        </List>
        <Box sx={{ flexGrow: 1 }}></Box>
        <List>
          <ListItem button onClick={() => setActiveTab("Logout")} sx={{ color: "#d32f2f" }}>
            <ListItemIcon sx={{ color: "#d32f2f" }}><ExitToApp /></ListItemIcon>
            <ListItemText primary="Logout" />
          </ListItem>
        </List>
      </Drawer>
      
      {/* Main Content */}
      <Box sx={{ flexGrow: 1, display: "flex", flexDirection: "column", pt: 8 }}>
        <Box sx={{ flexGrow: 1, p: 3, display: "flex", justifyContent: "center", alignItems: "center", backgroundColor: "rgba(100, 200, 225, 0.3)", minHeight: "100vh" }}>
          <Typography variant="h4" fontWeight="bold">
            {activeTab === "Dashboard" ? "Welcome to the Dashboard" :
             activeTab === "Vote" ? "Cast Your Vote Here" :
             activeTab === "Results" ? "Election Results" :
             "Logging Out..."}
          </Typography>
        </Box>
      </Box>
    </Box>
  );
};

export default Dashboard;
